def test_the_readme_shows_every_example() -> None:
    assert len(README_BLOCKS) >= len(EXAMPLES) >= 9
    assert "pip install tungoai" in README
    assert "https://api.tungo.kz" in README
    for name in EXAMPLES:
        source = (ROOT / "examples" / name).read_text(encoding="utf-8")
        begin, end = source.index("# [readme]\n") + len("# [readme]\n"), source.index("# [/readme]")
        assert source[begin:end].strip("\n") + "\n" in README_BLOCKS, f"README.md does not show examples/{name}"


